template<int N>
struct Factorial {
    // Recursive instantiation for compile-time calculation
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Full specialization (Base Case - Compile-time 'Polymorphism')
template<>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Example usage: calculation performed entirely by the compiler
constexpr int TMP_Result = Factorial<4>::value; // 24
// Memory Layout: Result is hardcoded into the binary
// No runtime calculation or vtable overhead involved
constexpr int V = TMP_Result;
